def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    objects = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                obj = (color, r + 1, c + 1, set((y, x) for y in range(r, r + 3) for x in range(c, c + 3)))
                if all((o[1], o[2]) != (obj[1], obj[2]) for o in objects):
                    objects.append(obj)
    for color, r, c, _ in objects:
        for x in range(w):
            out[r][x] = color
        for y in range(h):
            out[y][c] = color
    for color, _, _, cells in objects:
        for y, x in cells:
            out[y][x] = color
    for color_a, row_a, col_a, _ in objects:
        for color_b, row_b, col_b, _ in objects:
            if color_a != color_b:
                out[row_a][col_b] = 0
                out[row_b][col_a] = 0
    return out
